const inputData = $input.all();
const outputData = [];

for (const item of inputData) {
  const data = item.json;

  // Pass all data as-is and just add the link field
  const passedData = {
    ...data, // Keep everything exactly as it was
    link: "https://docs.google.com/spreadsheets/d/17rcNd_ZpUQLm0uWEVbD-NY6GyFUkrD4BglvawlyBygM/edit?gid=540316831#gid=540316831" // Add your link here
  };

  outputData.push({ json: passedData });
}

return outputData;
